DECLARE
    a1_level_id INTEGER;
    a2_level_id INTEGER;
    b1_level_id INTEGER;
    b2_level_id INTEGER;
    c1_level_id INTEGER;
    c2_level_id INTEGER;
BEGIN
    -- Get level IDs
    SELECT id INTO a1_level_id FROM levels WHERE level = 'A1';
    SELECT id INTO a2_level_id FROM levels WHERE level = 'A2';
    SELECT id INTO b1_level_id FROM levels WHERE level = 'B1';
    SELECT id INTO b2_level_id FROM levels WHERE level = 'B2';
    SELECT id INTO c1_level_id FROM levels WHERE level = 'C1';
    SELECT id INTO c2_level_id FROM levels WHERE level = 'C2';


    -- A1 Level Words (split by individual meanings)
    ON CONFLICT (word, meaning) DO NOTHING;

    -- A2 Level Words (368 words)
    ON CONFLICT (word, meaning) DO NOTHING;

    ON CONFLICT (word, meaning) DO NOTHING;

    ON CONFLICT (word, meaning) DO NOTHING;

    ON CONFLICT (word, meaning) DO NOTHING;

    -- B1 Level Words (108 words)
    ON CONFLICT (word, meaning) DO NOTHING;

    ON CONFLICT (word, meaning) DO NOTHING;

    -- Auto-categorize words by part of speech
    SELECT c.id, w.id 
    FROM categories c, words w 
    WHERE c.category = 'verbs' AND w.part_of_speech = 'verb'
    ON CONFLICT (category_id, word_id) DO NOTHING;

    SELECT c.id, w.id 
    FROM categories c, words w 
    WHERE c.category = 'adjectives' AND w.part_of_speech = 'adjective'
    ON CONFLICT (category_id, word_id) DO NOTHING;

    SELECT c.id, w.id 
    FROM categories c, words w 
    WHERE c.category = 'numbers' AND w.part_of_speech = 'numeral'
    ON CONFLICT (category_id, word_id) DO NOTHING;

    SELECT c.id, w.id 
    FROM categories c, words w 
    WHERE c.category = 'prepositions' AND w.part_of_speech = 'preposition'
    ON CONFLICT (category_id, word_id) DO NOTHING;

    SELECT c.id, w.id 
    FROM categories c, words w 
    WHERE c.category = 'articles' AND w.part_of_speech = 'article'
    ON CONFLICT (category_id, word_id) DO NOTHING;

    SELECT c.id, w.id 
    FROM categories c, words w 
    WHERE c.category = 'pronouns' AND w.part_of_speech = 'pronoun'
    ON CONFLICT (category_id, word_id) DO NOTHING;

END $$;

